+
+    public int dequeue() {
+        ensureNotEmpty();
+
+        int removedValue = elements[front];
+        front = advance(front);
+        size--;
+        return removedValue;
+    }
+
+    public int getFront() {
+        ensureNotEmpty();
+        return elements[front];
+    }
+
+    public int getRear() {
+        ensureNotEmpty();
+        return elements[lastElementIndex()];
+    }
+
+    public boolean isEmpty() {
+        return size == 0;
+    }
+
+    public boolean isFull() {
+        return size == elements.length;
+    }
