+        if (isEmpty()) {
+            throw new IllegalStateException("Queue is empty.");
+        }
+    }
+
+    private int nextInsertIndex() {
+        return (front + size) % elements.length;
+    }
+
+    private int lastElementIndex() {
+        return (front + size - 1 + elements.length) % elements.length;
